    // Compare component by component, longest wins on a tie.
    let mut i = 0;
    while i < a.parts.len() && i < b.parts.len() {
        let ord = a.parts[i].cmp(&b.parts[i]);
        if ord != std::cmp::Ordering::Equal {
            return ord;
